def try(h, spec)
  p = ActionController::Parameters.new(h)
  r = p.expect(spec)
  puts "#{h.inspect} => #{r.to_h.inspect}"
rescue => e
  puts "#{h.inspect} => #{e.class}: #{e.message}"
end
spec = { ticket: [:status, comment: [:body, :public]] }
