try({ticket: {status: ["a"]}}, spec)
try({ticket: {status: {"a"=>1}}}, spec)
puts ActiveRecord::Base.instance_method(:public) rescue puts "no public instance method: #{$!.class}"
puts ActiveRecord::AttributeMethods::ClassMethods.instance_method(:dangerous_attribute_method?).owner
puts User.dangerous_attribute_method?("public")
'

